    def disaplay_result(self):
        # self.v_layout = QVBoxLayout(self.frame)
        self.result_form = QtWidgets.QFormLayout(self.frame)
        num = 1
        
        #create scroll bar for display result
        self.topFiller_gobuster = QWidget()
        self.topFiller_gobuster.setMinimumSize(610, 1000)
        self.scroll_gobuster = QScrollArea(self.frame)
        self.scroll_gobuster.setWidget(self.topFiller_gobuster)
        self.scroll_gobuster.setGeometry(0, 0, 680, 490)
        layout_goresult = QVBoxLayout(self.topFiller_gobuster)
        
        for loop in self.result_list:
            Ui_MainWindow_Gobuster_Result.Gobuster_Result.append(loop["url"])

            #set url label
            label_text = f'{str(num)}. {loop["url"]}'
            self.url_location = loop["url"]
            self.lbl_url = QtWidgets.QLabel(self.frame)
            self.lbl_url.setObjectName(label_text)
            self.lbl_url.setText(label_text)
            self.lbl_url.adjustSize()
            self.result_form.addRow(self.lbl_url)

            #set result photo
            try:
                label_text = f'{str(num)}. photo'
                self.lbl_pho = QtWidgets.QLabel(self.frame)
                photo_location = loop["png_path"]
                if loop["png_path"] == "False":
                    self.lbl_pho.setText("Not Photo")
                    self.lbl_pho.adjustSize()
                    pass
                else:
                    self.lbl_pho.setPixmap(QtGui.QPixmap(photo_location))
                    self.lbl_pho.resize(672, 378)
                    self.lbl_pho.adjustSize()
                    self.result_form.addRow(self.lbl_pho)
            except:
                self.lbl_pho.setText("Not Photo")
                pass


            #set result button
            self.btn_url = openurlbutton(f'Open the Link {num}.', loop["url"])
            self.btn_url.clicked.connect(partial(self.button_clicked_webbrowser, self.btn_url.link))
            self.result_form.addRow(self.btn_url)

            
            layout_goresult.addWidget(self.lbl_url)
            layout_goresult.addWidget(self.lbl_pho)
            layout_goresult.addWidget(self.btn_url)
            #layout_goresult.addWidget(self.result_form)

            self.frame.adjustSize()
            self.topFiller_gobuster.adjustSize()

            num += 1
        
        #layout_goresult.addWidget(self.url_location)
        
    def thread_open_url_link(self, link):
        webbrowser.open(link)
        pass

    def button_clicked_webbrowser(self, link):
        thread_open_url = threading.Thread(target=self.thread_open_url_link(link))
        thread_open_url.start()
        pass

